// Источник: web-тест .qa/e2e/tests/important-dates/id-03-memorial-future-sunset-adar.spec.ts, план .qa/e2e/specs/important-dates.md (17.3), кейс .qa/tests/important-dates/ID-03-azkara-after-sunset-future-adar.md
// Тикет #6a86f7e6. Опора: реджект 27.09 п.1, 3, 5 (ответ 28.09); реджект 29.09 (ответ 30.09) — אדר א׳/ב׳.
// @data: создаёт אזכרה «QA-AUTO-נפטר» (14.03.2025, после заката); в finally удаляются ВСЕ «QA-AUTO-…».
// Только реальная дата устройства (page.clock на телефоне нет): если ближайший ט״ו אדר не в מעוברת (нет אדר א׳) — тест пропускается.
import { $$, driver, expect } from '@wdio/globals';
import { byLabel, byLabelStartsWith, byTextContains, tapLabel, tapText, expectTextContains, swipeUp } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { addDays, daysInMonth, dotDate, gregMonthName, isoDate, nextHebrewDay } from '../../../e2e/tests/_helpers/dates.ts';

function hebrewMonthOf(d: Date) {
  return new Intl.DateTimeFormat('he-u-ca-hebrew', { month: 'long' }).format(d);
}
function nextAdar15(from: Date) {
  const first = nextHebrewDay(from, 15, (m) => m.startsWith('אדר'));
  if (!first || !/א׳$/.test(hebrewMonthOf(first))) return null;
  const second = nextHebrewDay(addDays(first, 1), 15, (m) => m === 'אדר ב׳');
  return second ? { first, second } : null;
}
const editButtons = () => (driver.isAndroid
  ? $$('android=new UiSelector().descriptionMatches(".*QA-AUTO-.*: פתיחה לעריכה")').getElements()
  : $$('-ios predicate string:name MATCHES ".*QA-AUTO-.*: פתיחה לעריכה"').getElements());
async function homeDates() {
  await goTab('בית');
  const add = await byLabel('הוספת תאריך חשוב');
  for (let i = 0; i < 8 && !(await add.isDisplayed().catch(() => false)); i++) await swipeUp();
  await add.waitForDisplayed({ timeout: 20000 });
}
async function deleteQaDates() {
  await toHome();
  await homeDates();
  for (let guard = 0; guard < 10; guard++) {
    const list = await editButtons();
    if (list.length === 0) break;
    await list[0].click();
    await tapText('מחיקת התאריך');
    await tapText('מחיקה');
    await driver.waitUntil(async () => (await editButtons()).length < list.length, { timeout: 15000 });
  }
}

describe('Важные даты и אזכרות', () => {
  afterEach(async () => { await toHome(); });

  it('ID-03 אזכרה — будущая дата недоступна, «אחרי השקיעה» сдвигает еврейский день, אדר א׳/ב׳ #6a86f7e6 @data', async function () {
    const today = new Date();
    const adar = nextAdar15(today);
    if (!adar) this.skip();
    const Y = today.getFullYear();
    const M = today.getMonth();
    const D = today.getDate();
    const iso = (y: number, m0: number, d: number) => isoDate(new Date(y, m0, d, 12));
    try {
      // 1. «+» → «אזכרה»; имя; дни после сегодня недоступны, «החודש הבא» неактивна.
      await homeDates();
      await tapLabel('הוספת תאריך חשוב');
      await tapText('אזכרה');
      await (await byLabel('שם הנפטר')).setValue('QA-AUTO-נפטר');
      for (let d = D + 1; d <= daysInMonth(Y, M); d++) {
        const day = await byLabelStartsWith(`${iso(Y, M, d)}, `);
        await expect(day).toBeDisabled();
        expect(await day.getAttribute(driver.isAndroid ? 'content-desc' : 'name')).toMatch(/לא ניתן לבחור תאריך עתידי$/);
      }
      await expect(byLabelStartsWith(`${iso(Y, M, D)}, `)).toBeEnabled();
      await expect(byLabel('החודש הבא')).toBeDisabled();

      // Выбор месяца/года: будущие месяцы и «השנה הבאה» неактивны.
      await tapLabel(`${gregMonthName(Y, M)} ${Y}: בחירת שנה וחודש`);
      await expect(byLabel('השנה הבאה')).toBeDisabled();
      for (let m = M + 1; m <= 11; m++) {
        await expect(byLabelStartsWith(`${gregMonthName(Y, m)} ${Y}, לא ניתן לבחור תאריך עתידי`)).toBeDisabled();
      }

      // 2. «השנה הקודמת» до 2025 → «מרץ 2025» → 14; пояснение (י״ד אדר; в מעוברת — оба אדר).
      for (let y = Y; y > 2025; y--) await tapLabel('השנה הקודמת');
      await tapLabel('מרץ 2025');
      await (await byLabelStartsWith('2025-03-14, ')).click();
      await expectTextContains('יישמר: 14.03.2025 · י״ד אדר תשפ״ה');
      await expectTextContains('האזכרה תסומן בכל שנה ב־י״ד אדר.');
      await expectTextContains('בשנה מעוברת, שיש בה שני חודשי אדר, האזכרה תסומן גם ב־י״ד אדר א׳ וגם ב־י״ד אדר ב׳.');

      // 3. «הפטירה הייתה אחרי השקיעה» → ט״ו אדר → «הוסף תאריך».
      await tapLabel('הפטירה הייתה אחרי השקיעה');
      await expectTextContains('יישמר: 14.03.2025 · ט״ו אדר תשפ״ה — הפטירה אחרי השקיעה');
      await expectTextContains('האזכרה תסומן בכל שנה ב־ט״ו אדר.');
      await expectTextContains('בשנה מעוברת, שיש בה שני חודשי אדר, האזכרה תסומן גם ב־ט״ו אדר א׳ וגם ב־ט״ו אדר ב׳.');
      await tapText('הוסף תאריך');
      await expect(byLabel('שם הנפטר')).not.toBeDisplayed();

      // 4. Запись на «בית»: «האזכרה הבאה: ט״ו אדר א׳ – … · ט״ו אדר ב׳ – …»; в правке checkbox отмечен.
      const open = await byLabel('אזכרה, QA-AUTO-נפטר: פתיחת סדר האזכרה');
      for (let i = 0; i < 6 && !(await open.isDisplayed().catch(() => false)); i++) await swipeUp();
      await open.waitForDisplayed({ timeout: 20000 });
      await expectTextContains(`האזכרה הבאה: ט״ו אדר א׳ – ${dotDate(adar!.first)} · ט״ו אדר ב׳ – ${dotDate(adar!.second)}`);
      await tapLabel('אזכרה, QA-AUTO-נפטר: פתיחה לעריכה');
      const cb = await byLabel('הפטירה הייתה אחרי השקיעה');
      await cb.waitForDisplayed();
      expect(driver.isAndroid
        ? (await cb.getAttribute('checked')) === 'true'
        : ['1', 'true'].includes(String(await cb.getAttribute('value')))).toBe(true);
      await tapLabel('סגירה');
    } finally {
      // 5. Уборка.
      await deleteQaDates();
      await expect(byTextContains('QA-AUTO-')).not.toBeDisplayed();
    }
  });
});
